-- READ ONLY. Inspect through the verified project connection. The project_ref
-- label is the intended target, not independent proof of connection identity.
-- Private local rehearsal input: contains function/view definitions, no customer
-- rows or migration seed data. Never publish this snapshot or environment values.
-- Excluded suspicious function literals make the rehearsal fail closed.
with catalog_snapshot as (
select jsonb_build_object(
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity) order by n.nspname,c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','storage') and c.relkind in ('r','p')),
 'columns',(select coalesce(jsonb_agg(jsonb_build_object('key',table_schema||'.'||table_name||'.'||column_name,'type',udt_schema||'.'||udt_name,'nullable',is_nullable,'default_hash',md5(coalesce(column_default,''))) order by table_schema,table_name,column_name),'[]') from information_schema.columns where table_schema in ('public','storage')),
 'enums',(select coalesce(jsonb_agg(jsonb_build_object('key',n.nspname||'.'||t.typname||'.'||e.enumlabel,'order',e.enumsortorder) order by n.nspname,t.typname,e.enumsortorder),'[]') from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname='public'),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('key',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')','definition_hash',md5(pg_get_functiondef(p.oid)),'security_definer',p.prosecdef,'config',p.proconfig) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
 'indexes',(select coalesce(jsonb_agg(jsonb_build_object('key',schemaname||'.'||indexname,'definition_hash',md5(indexdef)) order by schemaname,indexname),'[]') from pg_indexes where schemaname in ('public','storage')),
 'triggers',(select coalesce(jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname||'.'||t.tgname,'definition_hash',md5(pg_get_triggerdef(t.oid)),'enabled',t.tgenabled) order by n.nspname,c.relname,t.tgname),'[]') from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','storage')),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('key',schemaname||'.'||tablename||'.'||policyname,'roles',roles,'command',cmd,'permissive',permissive,'using_hash',md5(coalesce(qual,'')),'check_hash',md5(coalesce(with_check,''))) order by schemaname,tablename,policyname),'[]') from pg_policies where schemaname in ('public','storage')),
 'table_grants',(select coalesce(jsonb_agg(jsonb_build_object('key',table_schema||'.'||table_name||'.'||grantee||'.'||privilege_type,'grantable',is_grantable) order by table_schema,table_name,grantee,privilege_type),'[]') from information_schema.role_table_grants where table_schema in ('public','storage') and grantee in ('anon','authenticated','service_role','PUBLIC')),
 'column_grants',(select coalesce(jsonb_agg(jsonb_build_object('key',n.nspname||'.'||c.relname||'.'||att.attname||'.'||coalesce(r.rolname,'PUBLIC')||'.'||acl.privilege_type,'grantable',acl.is_grantable) order by n.nspname,c.relname,att.attname,acl.grantee,acl.privilege_type),'[]') from pg_attribute att join pg_class c on c.oid=att.attrelid join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(att.attacl) acl left join pg_roles r on r.oid=acl.grantee where n.nspname in ('public','storage') and att.attnum>0 and not att.attisdropped and (r.rolname in ('anon','authenticated','service_role') or acl.grantee=0)),
 'function_grants',(select coalesce(jsonb_agg(jsonb_build_object('key',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||').' ||coalesce(r.rolname,'PUBLIC')||'.'||a.privilege_type,'grantable',a.is_grantable) order by p.proname,pg_get_function_identity_arguments(p.oid),a.grantee,a.privilege_type),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a left join pg_roles r on r.oid=a.grantee where n.nspname='public' and (r.rolname in ('anon','authenticated','service_role') or a.grantee=0) and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
 'buckets',(select coalesce(jsonb_agg(jsonb_build_object('key',id,'public',public) order by id),'[]') from storage.buckets)
) catalog
),schema_snapshot as (
select jsonb_build_object(
'enums',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'labels',(select jsonb_agg(e.enumlabel order by e.enumsortorder) from pg_enum e where e.enumtypid=t.oid)) order by t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype='e'),
'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(ad.adbin,ad.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in('r','p') and not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='e')),
'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'kind',k.contype,'definition',pg_get_constraintdef(k.oid)) order by case when k.contype='f' then 1 else 0 end,c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'),
'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'definition',case when pg_get_functiondef(p.oid) ~ '(sb_secret_[A-Za-z0-9_]+|AKIA[A-Z0-9]{16}|eyJ[A-Za-z0-9_-]{20,}\.|postgres(ql)?://[^[:space:]]+:[^[:space:]]+@)' then null else pg_get_functiondef(p.oid) end) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in('f','p') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),
'indexes',(select jsonb_agg(jsonb_build_object('name',i.indexname,'definition',i.indexdef) order by i.indexname) from pg_indexes i where i.schemaname='public' and not exists(select 1 from pg_constraint k where k.conindid=to_regclass('public.'||quote_ident(i.indexname)))),
'triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid)) order by t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal),
'views',(select jsonb_agg(jsonb_build_object('name',viewname,'definition',definition) order by viewname) from pg_views where schemaname='public'),
'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in('public','storage')),
'table_grants',(select jsonb_agg(to_jsonb(g)) from information_schema.role_table_grants g where table_schema='public' and grantee in('anon','authenticated','service_role','PUBLIC')),
'buckets',(select jsonb_agg(jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) order by id) from storage.buckets)
) schema_data
),extra_snapshot as (
select jsonb_build_object('default_acls',(select coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'kind',d.defaclobjtype,'grantee',case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,'privilege',a.privilege_type,'grantable',a.is_grantable)),'[]') from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a where n.nspname='public' or d.defaclnamespace=0),'special_columns',(select coalesce(jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'identity',a.attidentity,'generated',a.attgenerated)),'[]') from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and a.attnum>0 and not a.attisdropped and (a.attidentity<>'' or a.attgenerated<>''))) metadata
)
select jsonb_build_object('project_ref','ehqdzfopsrbwewtddiwq','observed_at',now(),'customer_rows_copied',0,
'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',array_length(statements,1),'statements_hash',md5(coalesce(array_to_string(statements,E'\n'),''))) order by version) from supabase_migrations.schema_migrations),
'schema',(select schema_data from schema_snapshot),'catalog',(select catalog from catalog_snapshot),'metadata',(select metadata from extra_snapshot),
'view_options',(select jsonb_agg(jsonb_build_object('name',c.relname,'options',c.reloptions) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='v'),
'extensions',(select jsonb_agg(jsonb_build_object('name',e.extname,'schema',n.nspname) order by e.extname) from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname in('pgcrypto','uuid-ossp'))) snapshot;
